/* Nikflix stack explorer.
 * Draws docs/explore/stack.json (generated by scripts/gen_stack.py) as an
 * interactive, layered map. Loaded on every page; only runs where
 * #nf-explorer exists. Uses Material's document$ so it works with
 * instant navigation.
 */
(function () {
  "use strict";

  const CAT_ORDER = ["networking", "security", "delivery", "observability", "media", "apps", "other"];
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const el = (html) => { const t = document.createElement("template"); t.innerHTML = html.trim(); return t.content.firstElementChild; };

  function mount(root) {
    if (root.dataset.ready) return;
    root.dataset.ready = "1";
    root.innerHTML = '<div class="nfx-loading">Loading the stack…</div>';
    fetch(root.dataset.src || "stack.json", { cache: "no-cache" })
      .then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); })
      .then((data) => new Explorer(root, data))
      .catch((e) => { root.innerHTML = `<div class="nfx-loading">Could not load stack.json (${esc(e.message)}).</div>`; });
  }

  class Explorer {
    constructor(root, data) {
      this.root = root;
      this.d = data;
      this.items = new Map(); // key -> {type, data}
      this.state = { q: "", cats: new Set(), planned: false, selected: null };
      this.src = (p) => `${data.repo}/blob/main/${p}`;
      this.tree = (p) => `${data.repo}/tree/main/${p}`;
      this.index();
      this.render();
      this.bind();
      const h = decodeURIComponent(location.hash.slice(1));
      if (h.startsWith("trace:") && this.appsById[h.slice(6)]) {
        this.select("app:" + h.slice(6));
        setTimeout(() => this.trace(), 300);
      } else {
        this.select(this.items.has(h) ? h : null);
      }
      requestAnimationFrame(() => this.wire());
    }

    index() {
      const d = this.d;
      d.external.forEach((x) => this.items.set("ext:" + x.id, { type: "ext", data: x }));
      d.proxmox.vlans.forEach((x) => this.items.set("vlan:" + x.id, { type: "vlan", data: x }));
      d.proxmox.nodes.forEach((x) => this.items.set("node:" + x.id, { type: "node", data: x }));
      d.kubernetes.vms.forEach((x) => this.items.set("vm:" + x.id, { type: "vm", data: x }));
      d.apps.forEach((x) => this.items.set("app:" + x.id, { type: "app", data: x }));
      this.items.set("cluster", { type: "cluster", data: d.kubernetes });
      this.appsById = Object.fromEntries(d.apps.map((a) => [a.id, a]));
    }

    // ------------------------------------------------------------ rendering

    render() {
      const d = this.d;
      const cats = CAT_ORDER.filter((c) => d.apps.some((a) => a.category === c));
      const vmsBy = (node) => d.kubernetes.vms.filter((v) => v.node === node);

      const chipsHTML = cats.map((c) =>
        `<button class="nfx-chip nfx-cat-${c}" data-cat="${c}" aria-pressed="false">${esc(d.categories[c])}</button>`).join("");

      const ext = d.external.map((x) => `
        <button class="nfx-card nfx-ext" data-key="ext:${x.id}">
          <b>${esc(x.name)}</b><small>${esc(x.ip || x.role)}</small>
        </button>`).join("");

      const vlans = d.proxmox.vlans.map((v) => `
        <button class="nfx-vlan nfx-vlan-${v.id}" data-key="vlan:${v.id}">
          <span class="nfx-vlan-id">VLAN ${v.id}</span><b>${esc(v.name)}</b><small>${esc(v.subnet)}</small>
        </button>`).join("");

      const nodes = d.proxmox.nodes.map((n) => `
        <div class="nfx-node ${n.status === "planned" ? "is-planned" : ""}" data-key="node:${n.id}" tabindex="0" role="button">
          <div class="nfx-node-head"><b>${esc(n.id)}</b>${n.founder ? '<span class="nfx-tag">founder</span>' : ""}${n.status === "planned" ? '<span class="nfx-tag">planned</span>' : ""}</div>
          <small>${esc(n.mgmt_ip)}</small>
          <div class="nfx-vms">${vmsBy(n.id).map((v) => `
            <button class="nfx-vm nfx-role-${v.role}" data-key="vm:${v.id}" title="${esc(v.id)}">
              ${v.role === "controlplane" ? "control plane" : "worker"}<small>.${esc(String(v.mgmt_ip).split(".").pop())}</small>
            </button>`).join("") || '<span class="nfx-empty">no VMs yet</span>'}
          </div>
        </div>`).join("");

      const columns = cats.map((c) => {
        const apps = d.apps.filter((a) => a.category === c);
        return `
          <div class="nfx-col" data-col="${c}">
            <h4 class="nfx-cat-${c}">${esc(d.categories[c])} <span>${apps.length}</span></h4>
            ${apps.map((a) => `
              <button class="nfx-app nfx-cat-${a.category}" data-key="app:${a.id}">
                <b>${esc(a.id)}</b>
                <span class="nfx-badges">
                  ${a.hosts.length ? '<i title="Has a web URL">web</i>' : ""}
                  ${a.sso === "forward-auth" ? '<i title="authentik forward-auth">fa</i>' : a.sso === "oidc" ? '<i title="authentik OIDC">oidc</i>' : ""}
                  ${a.storage.some((s) => s.startsWith("nfs")) ? '<i title="NFS from the NAS">nfs</i>' : ""}
                  ${a.lb_ips.length ? '<i title="LoadBalancer IP">lb</i>' : ""}
                  ${!a.auto_sync ? '<i class="warn" title="Manual sync">manual</i>' : ""}
                </span>
              </button>`).join("")}
          </div>`;
      }).join("");

      const k = d.kubernetes;
      this.root.innerHTML = `
        <div class="nfx">
          <div class="nfx-toolbar">
            <input class="nfx-search" type="search" placeholder="Search apps, namespaces, images, URLs…" aria-label="Search the stack">
            <div class="nfx-chips">${chipsHTML}</div>
            <label class="nfx-toggle"><input type="checkbox" class="nfx-planned"> Show planned nodes</label>
            <button class="nfx-trace md-button md-button--primary">▶ Trace a request</button>
          </div>
          <div class="nfx-body">
            <div class="nfx-canvas">
              <svg class="nfx-wires" aria-hidden="true"></svg>
              <section class="nfx-layer"><h3>Outside the cluster</h3><div class="nfx-row">${ext}</div></section>
              <section class="nfx-layer"><h3>Network · UniFi</h3><div class="nfx-row nfx-vlans">${vlans}</div></section>
              <section class="nfx-layer"><h3>Proxmox · ${esc(d.proxmox.cluster)}</h3><div class="nfx-row nfx-nodes">${nodes}</div></section>
              <section class="nfx-layer nfx-k8s" data-key="cluster">
                <h3>Kubernetes · ${esc(k.name)} <small>Talos ${esc(k.talos)} · API ${esc(k.endpoint)}</small></h3>
                <div class="nfx-entry">
                  <span>Ingress</span>
                  <code>*.${esc(d.domain)}</code> → <code>${esc(k.ingress_ip)}</code> → MetalLB → Traefik
                </div>
                <div class="nfx-cols">${columns}</div>
              </section>
            </div>
            <aside class="nfx-panel" aria-live="polite"></aside>
          </div>
          <div class="nfx-foot">
            <span>Legend:</span><i>web</i> URL <i>fa</i> forward-auth <i>oidc</i> OIDC login <i>nfs</i> NAS storage <i>lb</i> LoadBalancer IP <i class="warn">manual</i> manual sync
            <span class="nfx-gen">Generated from <a href="${esc(d.repo)}/commit/${esc(d.commit)}">${esc(d.commit)}</a> · ${esc(d.generated)} · <a href="${this.src("scripts/gen_stack.py")}">generator</a></span>
          </div>
        </div>`;
      this.canvas = this.root.querySelector(".nfx-canvas");
      this.svg = this.root.querySelector(".nfx-wires");
      this.panel = this.root.querySelector(".nfx-panel");
      this.applyFilters();
    }

    bind() {
      const r = this.root;
      r.querySelector(".nfx-search").addEventListener("input", (e) => { this.state.q = e.target.value.trim().toLowerCase(); this.applyFilters(); });
      r.querySelectorAll(".nfx-chip").forEach((b) => b.addEventListener("click", () => {
        const c = b.dataset.cat;
        this.state.cats.has(c) ? this.state.cats.delete(c) : this.state.cats.add(c);
        b.setAttribute("aria-pressed", this.state.cats.has(c));
        this.applyFilters();
      }));
      r.querySelector(".nfx-planned").addEventListener("change", (e) => { this.state.planned = e.target.checked; this.applyFilters(); });
      r.querySelector(".nfx-trace").addEventListener("click", () => this.trace());
      this.canvas.addEventListener("click", (e) => {
        const t = e.target.closest("[data-key]");
        if (!t || !this.canvas.contains(t)) return;
        e.stopPropagation();
        this.select(this.state.selected === t.dataset.key ? null : t.dataset.key);
      });
      this.canvas.addEventListener("keydown", (e) => {
        if (e.key === "Enter" && e.target.matches("[data-key]")) this.select(e.target.dataset.key);
        if (e.key === "Escape") this.select(null);
      });
      this.panel.addEventListener("click", (e) => {
        const go = e.target.closest("[data-goto]");
        if (go) {
          this.select(go.dataset.goto);
          this.node(go.dataset.goto)?.scrollIntoView({ block: "nearest", behavior: "smooth" });
        }
        if (e.target.closest('[data-action="clear"]')) this.select(null);
      });
      this.ro = new ResizeObserver(() => this.wire());
      this.ro.observe(this.canvas);
    }

    applyFilters() {
      const { q, cats, planned } = this.state;
      this.root.classList.toggle("nfx-show-planned", planned);
      this.root.querySelectorAll(".nfx-app").forEach((b) => {
        const a = this.appsById[b.dataset.key.slice(4)];
        const hay = [a.id, a.namespace, a.description, a.chart, ...(a.hosts || []), ...(a.images || [])].join(" ").toLowerCase();
        const ok = (!cats.size || cats.has(a.category)) && (!q || hay.includes(q));
        b.classList.toggle("is-dim", !ok);
      });
      this.root.querySelectorAll(".nfx-col").forEach((c) => {
        c.classList.toggle("is-hidden", cats.size > 0 && !cats.has(c.dataset.col));
      });
      requestAnimationFrame(() => this.wire());
    }

    // ------------------------------------------------------------ relations and wires

    related(key) {
      const out = new Set();
      if (!key) return out;
      const [type, id] = key.includes(":") ? key.split(/:(.+)/) : [key, null];
      const d = this.d;
      if (type === "app") {
        const a = this.appsById[id];
        if (a.hosts.length) { out.add("app:traefik"); out.add("ext:pihole"); }
        if (a.sso === "forward-auth") { out.add("app:authentik-outpost"); out.add("app:media-forward-auth"); out.add("app:authentik"); }
        if (a.sso === "oidc" && a.id !== "authentik") out.add("app:authentik");
        if (a.storage.some((s) => s.startsWith("nfs"))) out.add("ext:nas");
        if (a.lb_ips.length) { out.add("app:metallb"); out.add("app:metallb-pool"); }
        if (a.hosts.length) out.add("app:cert-manager");
        if (["cert-manager", "cluster-issuers"].includes(a.id)) out.add("ext:cloudflare");
        d.apps.filter((b) => b.namespace === a.namespace && b.id !== a.id && a.namespace !== "default").forEach((b) => out.add("app:" + b.id));
      } else if (type === "node") {
        d.kubernetes.vms.filter((v) => v.node === id).forEach((v) => out.add("vm:" + v.id));
        d.proxmox.vlans.forEach((v) => out.add("vlan:" + v.id));
      } else if (type === "vm") {
        const v = d.kubernetes.vms.find((x) => x.id === id);
        out.add("node:" + v.node); out.add("vlan:10"); out.add("cluster");
      } else if (type === "vlan") {
        d.proxmox.nodes.forEach((n) => out.add("node:" + n.id));
        if (id === "10") { d.kubernetes.vms.forEach((v) => out.add("vm:" + v.id)); out.add("app:metallb"); }
      } else if (type === "ext") {
        if (id === "nas") d.apps.filter((a) => a.storage.some((s) => s.startsWith("nfs"))).forEach((a) => out.add("app:" + a.id));
        if (id === "pihole") { out.add("app:traefik"); out.add("app:coredns"); }
        if (id === "cloudflare") { out.add("app:cert-manager"); out.add("app:cluster-issuers"); }
        if (id === "macmini") out.add("ext:nas");
      }
      return out;
    }

    node(key) { return this.root.querySelector(`[data-key="${CSS.escape(key)}"]`); }

    wire() {
      if (!this.svg || !this.canvas.isConnected) return;
      const box = this.canvas.getBoundingClientRect();
      this.svg.setAttribute("width", box.width);
      this.svg.setAttribute("height", box.height);
      this.svg.setAttribute("viewBox", `0 0 ${box.width} ${box.height}`);
      const pt = (elm, side) => {
        const r = elm.getBoundingClientRect();
        return { x: r.left - box.left + r.width / 2, y: (side === "top" ? r.top : r.bottom) - box.top };
      };
      const path = (a, b, cls) => {
        const my = (a.y + b.y) / 2;
        return `<path class="${cls}" d="M${a.x},${a.y} C${a.x},${my} ${b.x},${my} ${b.x},${b.y}"/>`;
      };
      const visible = (e) => e && e.offsetParent !== null && !e.closest(".is-hidden");
      let out = "";
      // Base wires: every VLAN reaches every node; VMs feed the cluster.
      this.d.proxmox.nodes.forEach((n) => {
        const ne = this.node("node:" + n.id);
        if (!visible(ne)) return;
        this.d.proxmox.vlans.forEach((v) => {
          const ve = this.node("vlan:" + v.id);
          out += path(pt(ve, "bottom"), pt(ne, "top"), `w w-vlan w-vlan-${v.id}${n.status === "planned" ? " w-planned" : ""}`);
        });
      });
      const k8s = this.root.querySelector(".nfx-k8s h3");
      this.d.kubernetes.vms.forEach((v) => {
        const ve = this.node("vm:" + v.id);
        if (visible(ve)) out += path(pt(ve, "bottom"), pt(k8s, "top"), "w w-vm");
      });
      // Selection wires.
      const sel = this.state.selected;
      if (sel) {
        const se = this.node(sel);
        this.related(sel).forEach((k) => {
          const re = this.node(k);
          if (!visible(se) || !visible(re) || k === "cluster") return;
          const a = se.getBoundingClientRect(), b = re.getBoundingClientRect();
          const down = a.top < b.top;
          out += path(pt(se, down ? "bottom" : "top"), pt(re, down ? "top" : "bottom"), "w w-sel");
        });
      }
      this.svg.innerHTML = out;
    }

    // ------------------------------------------------------------ selection and panel

    select(key) {
      this.state.selected = key;
      const rel = this.related(key);
      this.root.querySelectorAll("[data-key]").forEach((e) => {
        const k = e.dataset.key;
        e.classList.toggle("is-selected", k === key);
        e.classList.toggle("is-related", rel.has(k));
      });
      this.root.classList.toggle("nfx-has-sel", !!key);
      this.panel.innerHTML = key ? this.detail(key) : this.overview();
      try { history.replaceState(null, "", key ? "#" + key : location.pathname + location.search); } catch (e) {}
      this.wire();
    }

    row(label, value) { return value === undefined || value === null || value === "" || (Array.isArray(value) && !value.length) ? "" : `<dt>${label}</dt><dd>${value}</dd>`; }

    overview() {
      const d = this.d, apps = d.apps;
      const count = (f) => apps.filter(f).length;
      return `
        <h3>The stack</h3>
        <p class="nfx-muted">Click any card to see its details and connections. Use search and the category chips to filter.</p>
        <div class="nfx-kpis">
          <div><b>${d.proxmox.nodes.filter((n) => n.status === "running").length}</b><span>Proxmox nodes</span></div>
          <div><b>${d.kubernetes.vms.length}</b><span>Talos VMs</span></div>
          <div><b>${apps.length}</b><span>Applications</span></div>
          <div><b>${count((a) => a.hosts.length)}</b><span>Web apps</span></div>
          <div><b>${count((a) => a.sso)}</b><span>Behind SSO</span></div>
          <div><b>${count((a) => a.kind === "helm")}</b><span>Helm charts</span></div>
        </div>
        <p class="nfx-muted">This page is drawn from <code>stack.json</code>, which <code>scripts/gen_stack.py</code> builds from the repository on every deploy.</p>`;
    }

    detail(key) {
      const it = this.items.get(key);
      if (!it) return this.overview();
      const x = it.data;
      const link = (href, text) => `<a href="${esc(href)}" target="_blank" rel="noopener">${esc(text)}</a>`;
      const docs = (href, text) => `<a href="${href}">${esc(text)}</a>`;
      let h = "", dl = "", links = "";
      switch (it.type) {
        case "app": {
          h = `<span class="nfx-pill nfx-cat-${x.category}">${esc(this.d.categories[x.category])}</span><h3>${esc(x.id)}</h3><p>${esc(x.description)}</p>`;
          dl += this.row("Namespace", `<code>${esc(x.namespace)}</code>`);
          dl += this.row("Source", x.kind === "helm" ? `Helm <code>${esc(x.chart)}</code> ${esc(x.version)}` : `Raw manifests`);
          dl += this.row("Images", (x.images || []).map((i) => `<code>${esc(i)}</code>`).join("<br>"));
          dl += this.row("URL", x.hosts.map((u) => link("https://" + u, u)).join("<br>"));
          dl += this.row("Login", x.sso === "forward-auth" ? "authentik forward-auth" : x.sso === "oidc" ? "authentik OIDC" : x.hosts.length ? "App's own login" : "");
          dl += this.row("LB IP", x.lb_ips.map((i) => `<code>${esc(i)}</code>`).join(" "));
          dl += this.row("Storage", x.storage.map(esc).join("<br>"));
          dl += this.row("Ballast", x.ballast ? "Rightsized (resize mode)" : "");
          dl += this.row("Sync", x.auto_sync ? "Automated · prune · self-heal" : '<span class="warn">Manual</span>');
          links += link(this.src(x.source), "Application manifest");
          (x.values || []).forEach((v) => (links += link(this.src(v), "Values file")));
          if (x.manifests) links += link(this.tree(x.manifests), "Manifests folder");
          links += docs("../current/apps/", "Apps catalog");
          break;
        }
        case "node": {
          const vms = this.d.kubernetes.vms.filter((v) => v.node === x.id);
          h = `<span class="nfx-pill">${x.status === "planned" ? "Planned node" : "Proxmox node"}</span><h3>${esc(x.id)}</h3>`;
          dl += this.row("Management", `<code>${esc(x.mgmt_ip)}</code> · VLAN 10 · nic1/vmbr0`);
          dl += this.row("Corosync", `<code>${esc(x.corosync_ip)}</code> · VLAN 100 · nic0`);
          dl += this.row("Storage", `<code>${esc(x.storage_ip)}</code> · VLAN 80 · nic2`);
          dl += this.row("Role", x.founder ? "Cluster founder (node 1)" : x.status === "planned" ? "Future worker host" : "Member");
          dl += this.row("VMs", vms.map((v) => esc(v.id)).join("<br>"));
          dl += this.row("Note", x.nic2_override ? "USB NIC name pinned with <code>pve_nic2_mac_override</code>" : "");
          links += link(this.src(x.source), "Inventory");
          links += docs("../reference/networking/#per-node-cabling", "Cabling");
          links += docs(x.status === "planned" ? "../tutorials/add-a-node/" : "../current/hardware/", x.status === "planned" ? "Add a node" : "Hardware");
          break;
        }
        case "vm": {
          h = `<span class="nfx-pill">Talos VM · ${x.role === "controlplane" ? "control plane" : "worker"}</span><h3>${esc(x.id)}</h3>`;
          dl += this.row("VM ID", x.vmid);
          dl += this.row("Host", esc(x.node));
          dl += this.row("Size", `${x.vcpu} vCPU · ${x.memory_gib} GiB`);
          dl += this.row("Disks", `${x.boot_disk_gb} GB boot · ${x.data_disk_gb} GB data`);
          dl += this.row("IP", `<code>${esc(x.mgmt_ip)}</code>`);
          dl += this.row("Talos", esc(this.d.kubernetes.talos));
          links += link(this.src(x.source), "Terraform");
          links += link(this.tree("development/talos/patches"), "Talos patches");
          links += docs("../tutorials/build/talos/", "Talos setup");
          break;
        }
        case "vlan": {
          h = `<span class="nfx-pill">VLAN ${x.id}</span><h3>${esc(x.name)}</h3><p>${esc(x.carries)}</p>`;
          dl += this.row("Subnet", `<code>${esc(x.subnet)}</code>`);
          dl += this.row("Node NIC", `<code>${esc(x.nic)}</code>`);
          dl += this.row("Switch", esc(x.switch));
          dl += this.row("Tagging", "Native (untagged) on node ports");
          links += docs("../reference/networking/#vlans", "Networking reference");
          break;
        }
        case "ext": {
          h = `<span class="nfx-pill">Outside the cluster</span><h3>${esc(x.name)}</h3><p>${esc(x.role)}</p>`;
          dl += this.row("Address", x.ip ? `<code>${esc(x.ip)}</code>` : "");
          links += docs("../reference/networking/#other-devices-the-cluster-depends-on", "Networking reference");
          break;
        }
        case "cluster": {
          h = `<span class="nfx-pill">Kubernetes</span><h3>${esc(x.name)}</h3>`;
          dl += this.row("API", `<code>${esc(x.endpoint)}</code>`);
          dl += this.row("Talos", esc(x.talos));
          dl += this.row("Nodes", `${x.vms.filter((v) => v.role === "controlplane").length} control plane · ${x.vms.filter((v) => v.role === "worker").length} worker`);
          dl += this.row("Ingress", `<code>${esc(x.ingress_ip)}</code>`);
          links += docs("../current/platform/", "Platform");
          break;
        }
      }
      const rel = [...this.related(key)].filter((k) => this.items.has(k) && k !== "cluster");
      const relHTML = rel.length ? `<h4>Connected to</h4><div class="nfx-rel">${rel.map((k) => `<button data-goto="${esc(k)}">${esc(k.startsWith("vlan:") ? "VLAN " + k.slice(5) : k.split(":").pop())}</button>`).join("")}</div>` : "";
      return `${h}<dl>${dl}</dl>${relHTML}<div class="nfx-links">${links}</div>
        <button class="nfx-close" data-action="clear">Clear selection</button>`;
    }

    // ------------------------------------------------------------ request trace

    trace() {
      if (this.tracing) return;
      const sel = this.state.selected && this.state.selected.startsWith("app:") ? this.appsById[this.state.selected.slice(4)] : null;
      const target = sel && sel.hosts.length ? sel : this.appsById.sonarr || this.d.apps.find((a) => a.hosts.length);
      const host = target.hosts[0];
      const steps = [
        ["ext:pihole", `Browser asks Pi-hole for <code>${esc(host)}</code>. The wildcard answers <code>${esc(this.d.kubernetes.ingress_ip)}</code>.`],
        ["vlan:10", "The request reaches the management VLAN, where MetalLB answers ARP for the VIP."],
        ["app:metallb", "MetalLB hands the connection to the Traefik service."],
        ["app:traefik", "Traefik matches the host name and terminates TLS with a cert-manager certificate."],
      ];
      if (target.sso === "forward-auth") steps.push(["app:authentik-outpost", "Traefik asks the authentik outpost if the user is logged in. If not, the user is sent to log in."]);
      if (target.sso === "oidc") steps.push(["app:authentik", "The app sends the user to authentik to log in with OIDC."]);
      steps.push(["app:" + target.id, `Traefik proxies the request to <b>${esc(target.id)}</b> in namespace <code>${esc(target.namespace)}</code>.`]);
      if (target.storage.some((s) => s.startsWith("nfs"))) steps.push(["ext:nas", "The app reads and writes media on the NAS over NFS."]);

      this.tracing = true;
      this.select(null);
      this.root.classList.add("nfx-tracing");
      this.panel.innerHTML = `<h3>Request to ${esc(host)}</h3><ol class="nfx-steps">${steps.map((s) => `<li>${s[1]}</li>`).join("")}</ol>
        <p class="nfx-muted">Select a web app first to trace a request to it.</p>`;
      const lis = this.panel.querySelectorAll(".nfx-steps li");
      let prev = null;
      steps.forEach(([key], i) => setTimeout(() => {
        this.root.querySelectorAll(".is-trace").forEach((e) => e.classList.remove("is-trace"));
        const e = this.node(key);
        e?.classList.add("is-trace", "was-trace");
        lis.forEach((li, j) => li.classList.toggle("is-on", j <= i));
        if (prev && e) this.traceWire(prev, e);
        prev = e;
        if (i === steps.length - 1) setTimeout(() => {
          this.tracing = false;
          this.root.classList.remove("nfx-tracing");
          this.root.querySelectorAll(".is-trace, .was-trace").forEach((x) => x.classList.remove("is-trace", "was-trace"));
          this.wire();
        }, 2500);
      }, i * 900));
    }

    traceWire(a, b) {
      const box = this.canvas.getBoundingClientRect();
      const ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect();
      const p = (r) => ({ x: r.left - box.left + r.width / 2, y: r.top - box.top + r.height / 2 });
      const A = p(ra), B = p(rb), my = (A.y + B.y) / 2;
      const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
      path.setAttribute("d", `M${A.x},${A.y} C${A.x},${my} ${B.x},${my} ${B.x},${B.y}`);
      path.setAttribute("class", "w w-trace");
      this.svg.appendChild(path);
    }
  }

  function boot() {
    document.querySelectorAll("#nf-explorer").forEach(mount);
  }

  if (window.document$ && typeof window.document$.subscribe === "function") window.document$.subscribe(boot);
  else document.addEventListener("DOMContentLoaded", boot);
})();
